<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import type{DesignElement,DesignSnapshot,DesignOperation}from'@schubert/contracts';
 import MeasurementField from'./MeasurementField.svelte';
 import ReferencePicker from'../ReferencePicker.svelte';
 type Layer=Extract<DesignElement,{kind:'wall'}>['layers'][number];
 let{snapshot,element,materials=[],products=[],documents=[],actorId='',canConfirm=false,disabled=false,onchange}:{snapshot:DesignSnapshot;element:DesignElement;materials?:any[];products?:any[];documents?:any[];actorId?:string;canConfirm?:boolean;disabled?:boolean;onchange:(ops:DesignOperation[])=>void}=$props();
 const layers=$derived(element.kind==='room'?element.floorLayers:element.kind==='wall'||element.kind==='surface'?element.layers:[]);
 const sides:Record<string,string>={left:'Links der Wandrichtung',right:'Rechts der Wandrichtung',top:'Oberhalb / außen',bottom:'Unterhalb / innen'};
 function operations(next:Layer[]):DesignOperation[]{if(element.kind==='wall')return[{type:'set_wall',elementId:element.id,layers:next}];if(element.kind==='surface')return[{type:'set_surface_spec',elementId:element.id,layers:next}];if(element.kind==='room')return[{type:'set_room_spec',elementId:element.id,floorLayers:next}];return[];}
 function update(index:number,changes:Partial<Layer>){onchange(operations(layers.map((layer,i)=>i===index?{...layer,...changes}:structuredClone($state.snapshot(layer)))));}
 function add(){const id=crypto.randomUUID(),measureId=id+':thickness',layer:Layer={id,materialSpecVersionId:'unassigned:material',productVariantVersionId:null,thicknessMeasureId:measureId,side:element.kind==='wall'?'left':element.kind==='room'?'bottom':'top'};onchange([{type:'set_design_target',measureId,valueMm:null},...operations([...structuredClone($state.snapshot(layers)),layer])]);}
 function remove(index:number){onchange(operations(layers.filter((_,i)=>i!==index)));}
 function order(index:number,delta:number){const next=structuredClone($state.snapshot(layers)),target=index+delta;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];onchange(operations(next));}
</script>
<div class="layer-editor"><h3>Schichtaufbau</h3><p>{element.kind==='room'?'Reihenfolge von der festgelegten Fertigfußbodenoberfläche nach unten.':element.kind==='wall'?'Reihenfolge je Wandseite vom Kern nach außen. Links und rechts folgen der Richtung vom Anfangs- zum Endknoten.':'Reihenfolge je Seite von der lokalen Bezugsebene nach außen. Oberhalb folgt der lokalen Flächennormalen.'} Fehlende Stärken verhindern eine erfundene Lage nachfolgender Schichten.</p>
 {#each layers as layer,index (layer.id)}<article><header><strong>Schicht {index+1}</strong><div><button type="button" aria-label={`Schicht ${index+1} nach vorne`} onclick={()=>order(index,-1)} disabled={disabled||index===0}>↑</button><button type="button" aria-label={`Schicht ${index+1} nach hinten`} onclick={()=>order(index,1)} disabled={disabled||index===layers.length-1}>↓</button><button type="button" onclick={()=>remove(index)} {disabled}>Entfernen</button></div></header>
  {#if element.kind!=='room'}<label>Bauteilseite<select use:searchableSelect={layer.side} value={layer.side} onchange={event=>update(index,{side:event.currentTarget.value as Layer['side']})} {disabled}>{#each Object.entries(sides).filter(([side])=>element.kind==='wall'||side==='top'||side==='bottom') as [key,name]}<option value={key}>{name}</option>{/each}</select></label>{/if}
  <label for={'layer-material-'+layer.id}>Konkreter Materialstand</label><ReferencePicker id={'layer-material-'+layer.id} reference="material-versions" initial={materials.map(m=>({id:m.version_id??m.id,name:m.name??m.label}))} bind:value={()=>layer.materialSpecVersionId.startsWith('unassigned')?'':layer.materialSpecVersionId,v=>update(index,{materialSpecVersionId:v||'unassigned:material'})}/>
  <label for={'layer-product-'+layer.id}>Eingefrorener Beschaffungsartikel</label><ReferencePicker id={'layer-product-'+layer.id} reference="product-versions" initial={products.map(p=>({id:p.product_variant_version_id??p.version_id??p.id,name:(p.name??p.sku)+' · '+(p.sku??'')}))} bind:value={()=>layer.productVariantVersionId??'',v=>update(index,{productVariantVersionId:v||null})}/>
  <MeasurementField {snapshot} measureId={layer.thicknessMeasureId} label={`Schicht ${index+1} · Stärke`} {actorId} {canConfirm} evidence={documents} {disabled} onchange={onchange}/>
 </article>{:else}<p>Noch kein Schichtaufbau festgelegt.</p>{/each}<button class="btn small" type="button" onclick={add} {disabled}>Schicht ergänzen</button>
</div>
<style>.layer-editor{font-size:13px;line-height:1.65;margin-top:20px;border-top:1px solid var(--line);padding-top:18px}.layer-editor h3{font-size:14px;font-weight:600}.layer-editor p{font-size:12px;color:var(--muted)}.layer-editor article{padding:14px;border:1px solid var(--line);background:var(--paper);border-radius:4px;margin:14px 0}.layer-editor header{display:flex;justify-content:space-between;gap:8px;align-items:center;font-size:13px}.layer-editor header div{display:flex;gap:7px}.layer-editor header button{border:0;background:none;color:var(--forest);padding:5px 2px;font:inherit;font-size:12px;min-width:22px;min-height:34px;cursor:pointer}.layer-editor label{display:block;font-size:13px;margin:14px 0}.layer-editor :global(select){display:block;box-sizing:border-box;width:100%;font:inherit;font-size:14px;background:var(--paper);color:var(--ink);padding:10px;margin-top:7px;border:1px solid var(--line);border-radius:4px;min-height:44px}.layer-editor button:focus-visible,.layer-editor :global(select:focus-visible){outline:2px solid var(--forest);outline-offset:2px}@media(max-width:720px){.layer-editor :global(select),.layer-editor button{font-size:16px;min-height:48px}.layer-editor header{align-items:flex-start;flex-direction:column}}</style>
